(() => {
  const q = s => document.querySelector(s);
  const txt = e => e ? e.innerText.replace(/\n+/g,' | ').trim() : null;
  const desc = document.querySelector('.task-description, [id*="description"], .markdown-text');
  const dd = Array.from(document.querySelectorAll('ul.task-list li, li')).filter(li=>/Due date/i.test(li.innerText||''));
  const comments = Array.from(document.querySelectorAll('#comments .comment, .comment')).map(c=>({text: (c.querySelector('.comment-content, .markdown')||c).innerText.trim().slice(0,200)}));
  const col = Array.from(document.querySelectorAll('li')).filter(li=>/^Column:/i.test((li.innerText||'').trim()));
  return {
    h1: txt(document.querySelector('h1')),
    heading_task: txt(q('h2')),
    title: txt(document.querySelector('h2.feed-title, .task-title, h3')),
    descPanel: txt(document.querySelector('#task-description, .task-description-wrapper, .task-description')),
    dueDateLis: dd.map(l=>l.innerText.replace(/\n+/g,' | ').trim()),
    columnLis: col.map(l=>l.innerText.replace(/\n+/g,' | ').trim()),
    commentsSection: txt(document.querySelector('#comments')),
    comments,
    bodySnippet: (function(){ const m = document.body.innerText.match(/Description[\s\S]{0,300}/); return m?m[0]:null; })()
  };
})()
